def create_default_vouchers(apps, schema_editor):
    """Pindahkan diskon WA lama (Pengaturan toko) menjadi voucher + tambah voucher gratis ongkir."""
    StoreSettings = apps.get_model("store", "StoreSettings")
    Voucher = apps.get_model("store", "Voucher")
    store = StoreSettings.objects.filter(pk=1).first()
    percent = Decimal(str(store.whatsapp_discount_percent)) if store else Decimal("5")
    on_promo = bool(store.whatsapp_discount_on_promo) if store else False
    if percent > 0 and not Voucher.objects.filter(code="WAHEMAT5").exists():
        Voucher.objects.create(
            code="WAHEMAT5",
            title=f"Diskon {percent.normalize():f}% pesan via WhatsApp",
            terms="Khusus pesanan lewat website (pesan via WhatsApp).",
            voucher_type="PERCENT", value=percent, max_discount=500000, min_purchase=1000000,
            for_whatsapp=True, for_midtrans=False, exclude_promo=not on_promo, can_combine=True,
            is_public=True, show_in_popup=True, sort_order=1,
        )
    if not Voucher.objects.filter(code="ONGKIR40").exists():
        Voucher.objects.create(
            code="ONGKIR40",
            title="Gratis ongkir s/d Rp40.000",
            terms="Potongan ongkir dipotong saat admin mengonfirmasi ongkir.",
            voucher_type="FREE_SHIPPING", value=40000, min_purchase=1000000,
            for_whatsapp=True, for_midtrans=True, exclude_promo=False, can_combine=True,
            is_public=True, show_in_popup=False, sort_order=2,
        )


